      p.closed();
      assertEquals(1, primary.getSuppressed().length);
      c.rollback();
    }
    assertThrows(NullPointerException.class, () -> new StepCleanupService(null));
    var service = new StepCleanupService(() -> 0);
    assertThrows(
        NullPointerException.class,
