                  if (bad.equals("parentDrift"))
                    values.put(FIXTURE_INO_4BE7C1E0, (Long) values.get(FIXTURE_INO_4BE7C1E0) + 1);
                  if (bad.equals("lateNonroot")) f.effective = 1;
