    Instant cutoff = Instant.parse("2026-09-30T00:00:00Z");
    Instant started = cutoff.plusSeconds(1);
    for (long id : new long[] {-1, 0, 1_000_000_000_000L, Long.MAX_VALUE}) {
      var failure =
          assertThrows(
              IllegalArgumentException.class,
