                  new CleanupWorkerRequest.Expiry.PriorExpiry(
                      run, cutoff, 42, attempt, started, started));
      assertEquals("invalid batch step identity", failure.getMessage());
      assertNull(failure.getCause());
    }
    for (Instant invalid :
        List.of(
            cutoff.minusNanos(1000),
