  void quiescentStates() {
    for (String active :
        List.of(
            "inactive", "active", FIXTURE_FAILED_33D04BD7, "activating", "deactivating", "unknown"))
      for (String sub :
          List.of("dead", "exited", FIXTURE_FAILED_33D04BD7, "running", "start", "unknown")) {
        String input =
