    assertTrue(events.indexOf("intent") < events.indexOf("start"));
    assertThrows(IOException.class, () -> cycle.execute(actual -> fail("single start lifetime")));
    live.recheck();
    assertTrue(live.stoppedJournal().isEmpty());
