    for (boolean expired : List.of(false, true)) {
      reset();
      seedApi(expired);
      try (var f = new Fixture()) {
        f.realApi = true;
        f.enqueue(1);
        assertEquals(
            expired
                ? RevocationRetryCoordinator.Outcome.RETAINED
                : RevocationRetryCoordinator.Outcome.CONFIRMED,
            f.coordinator().dispatchOne());
        try (var c = db.api();
            var s = c.createStatement();
