        assertEquals(1, count("select count(*) from schubert.app_logs", false));
        if (expired) {
          state(1, REQUESTED.plusSeconds(35), "SESSION_INVALID");
          f.clock.set(REQUESTED.plusSeconds(35));
          f.expectedStamp = "20260908090035123";
